<template><main class="page"><header><h1>Borrowers</h1><nav><RouterLink to="/checkout">Checkout</RouterLink> · <RouterLink to="/items">Items</RouterLink> · <RouterLink to="/settings">Settings</RouterLink></nav></header><p v-if="loading">Loading…</p><p v-else-if="error" class="error">{{ error }}</p><table v-else><thead><tr><th>Name</th><th>Borrower ID</th></tr></thead><tbody><tr v-for="borrower in borrowers" :key="borrower.id"><td>{{ borrower.username }}</td><td>{{ borrower.student_id }}</td></tr></tbody></table></main></template>
<script setup lang="ts">import{onMounted,ref}from"vue";import{RouterLink}from"vue-router";import{authenticatedSelect}from"../../services/authenticatedDataClient";type Row={id:string;username:string;student_id:string};const borrowers=ref<Row[]>([]),loading=ref(true),error=ref("");onMounted(async()=>{try{borrowers.value=await authenticatedSelect<Row[]>("students",{select:"id,username,student_id",deleted_at:"is.null",order:"username.asc"});}catch{error.value="Unable to load borrowers."}finally{loading.value=false;}});</script>
